    const u = this.mesh.userData;
    const amp = clamp(this.speed / 8.5, 0.08, 1) * 0.7;
    u.legL.rotation.x = s * amp; u.legR.rotation.x = -s * amp;
    u.armL.rotation.x = -s * amp * 0.8; u.armR.rotation.x = s * amp * 0.8;
